summary:
bash: cp ~/.bashrc /tmp/bashrc.bak
BLOCK='# >>> klee >>>
export PATH=/usr/local/bin:${PATH}
export CPATH=/usr/local/include${CPATH:+:$CPATH}
export LD_LIBRARY_PATH=/usr/local/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}
# <<< klee <<<
'
grep -q '>>> klee >>>' ~/.bashrc || { printf '%s' "$BLOCK" | cat - ~/.bashrc > /tmp/bashrc.new && cat /tmp/bashrc.new > ~/.bashrc; }
echo "bashrc updated"
head -15 ~/.bashrc

