bash: cat > /tmp/klee-install/t.c <<'EOF'
#include <klee/klee.h>
int main(void) {
  int x;
  klee_make_symbolic(&x, sizeof(x), "x");
  if (x == 5) { int zero = 0; x = x / zero; }   /* reachable division by zero */
  return 0;
}
EOF
bash -c 'source ~/.bashrc; clang-16 -emit-llvm -c -g -O0 /tmp/klee-install/t.c -o /tmp/klee-install/t.bc && klee --output-dir=/tmp/klee-install/out /tmp/klee-install/t.bc; echo "klee exit=$?"; ls /tmp/klee-install/out'

